(function importSuppliedProductsOnce(){
  const importFlag = 'sonboir_import_15_products_v1_done';
  if (localStorage.getItem(importFlag) === 'yes') return;
  if (!Array.isArray(products)) products = [];
  const norm = v => String(v || '').trim().toLowerCase().replace(/\\s+/g, ' ');
  let added = 0;
  SONBOIR_IMPORT_15_PRODUCTS.forEach((item, index) => {
    const exists = products.some(p =>
      norm(p.name) === norm(item.name) &&
      norm(p.technical) === norm(item.technical)
    );
    if (!exists) {
      const copy = JSON.parse(JSON.stringify(item));
      copy.id = 'sonboir_import15_' + String(index + 1).padStart(3, '0');
      products.push(copy);
      added++;
    }
  });
  try {
    localStorage.setItem('sonboir_products', JSON.stringify(products));
    localStorage.setItem(importFlag, 'yes');
    if (added > 0) console.info('SONBOIR AGRI PRO: imported ' + added + ' products from supplied backup.');
  } catch (err) {
    console.error('Product import could not be saved:', err);
    alert('15 products load nahi ho paaye. Browser storage full ho sakta hai. Purana data backup karke dobara try karein.');
  }
})();

let customers = JSON.parse(localStorage.getItem('sonboir_customers') || '[]');
let notes = JSON.parse(localStorage.getItem('sonboir_notes') || '[]');
let sales = JSON.parse(localStorage.getItem('sonboir_sales') || '[]');
let purchases = JSON.parse(localStorage.getItem('sonboir_purchases') || '[]');
let suppliers = JSON.parse(localStorage.getItem('sonboir_suppliers') || '[]');
let customChemicals = JSON.parse(localStorage.getItem('sonboir_custom_chemicals') || '[]');
function allChemicals(){const seen=new Set();return [...DB.chemicals,...customChemicals].filter(x=>{const k=String(x.technical||'').trim().toLocaleLowerCase().replace(/\s+/g,' ');if(!k||seen.has(k))return false;seen.add(k);return true})}

const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

// Populate selects
const cats=[...new Set(allChemicals().map(x=>x.category))].sort();
cats.forEach(c=>{let o=document.createElement('option');o.value=c;o.textContent=c;$('catFilter').append(o);let z=o.cloneNode(true);$('chemCatFilter').append(z)});

// Populate searchable technical-name picker & compare list
let techSelect = $('technicalSelect');
let compareTech = $('compareTech');
[...new Set(allChemicals().map(x=>x.category))].sort().forEach(category=>{
  const option=document.createElement('option');
  option.value=category; option.textContent=category;
  $('techPickerCategory').appendChild(option);
});
allChemicals().forEach(x=>{
  let opt2 = document.createElement('option');
  opt2.value = x.technical;
  opt2.textContent = `${x.technical} (${x.category})`;
  compareTech.appendChild(opt2);
});
function filterTechnicalOptions(){
  const query=($('techPickerSearch').value||'').trim().toLowerCase();
  const category=$('techPickerCategory').value;
  const sort=$('techPickerSort').value;
  const current=$('technical').value.trim();
  let list=allChemicals().filter(x=>
    (!category||x.category===category) &&
    (!query||(x.technical+' '+x.category+' '+x.target+' '+x.crops).toLowerCase().includes(query))
  );
  if(sort==='az') list.sort((a,b)=>a.technical.localeCompare(b.technical));
  else if(sort==='za') list.sort((a,b)=>b.technical.localeCompare(a.technical));
  else list.sort((a,b)=>a.id-b.id);
  techSelect.innerHTML='<option value="">-- सूची से Technical Name चुनें --</option>';
  list.forEach(x=>{
    const option=document.createElement('option');
    option.value=x.technical;
    option.textContent=`${x.technical}  ·  ${x.category}`;
    techSelect.appendChild(option);
  });
  $('techPickerCount').textContent=`${list.length} / ${allChemicals().length} Technical Names मिले`;
  techSelect.value=list.some(x=>x.technical===current)?current:'';
}
function selectTechnicalOption(){
  if(!techSelect.value)return;
  $('technical').value=techSelect.value;
  $('techPickerSearch').value=techSelect.value;
}
function syncTechnicalPickerFromText(){
  const typed=$('technical').value.trim();
  if(!typed){$('techPickerSearch').value='';filterTechnicalOptions();return}
  $('techPickerSearch').value=typed;
  filterTechnicalOptions();
  const exact=allChemicals().find(x=>x.technical.toLowerCase()===typed.toLowerCase());
  if(exact)techSelect.value=exact.technical;
}
filterTechnicalOptions();

function saveAll(){
  try{
    localStorage.setItem('sonboir_products', JSON.stringify(products));
    localStorage.setItem('sonboir_customers', JSON.stringify(customers));
    localStorage.setItem('sonboir_notes', JSON.stringify(notes));
    localStorage.setItem('sonboir_sales', JSON.stringify(sales));
    localStorage.setItem('sonboir_purchases', JSON.stringify(purchases));
    localStorage.setItem('sonboir_suppliers', JSON.stringify(suppliers));
    localStorage.setItem('sonboir_custom_chemicals', JSON.stringify(customChemicals));
    renderStats();
    refreshOperationalViews();
    return true;
  }catch(err){
    console.error('Save failed',err);
    alert('डेटा सेव नहीं हो पाया। Browser Storage भर सकता है। तुरंत Backup डाउनलोड करें।');
    return false;
  }
}

function renderStats(){
  $('chemCount').textContent=allChemicals().length;
  $('prodCount').textContent=products.length;
  $('packCount').textContent=products.reduce((a,p)=>a+(p.packs||[]).length,0);
  $('custCount').textContent=customers.length;
  $('noteCount').textContent=notes.length;
}

function toggleTheme(){
  let b=document.body;
  let next=b.dataset.theme==='light'?'dark':'light';
  b.dataset.theme=next;
}

