document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{
  document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x===b));
  document.querySelectorAll('.view').forEach(x=>x.classList.toggle('hide',x.id!==b.dataset.tab));
});

// 1. SEARCH
function renderSearch(){
  const q=($('q')?.value||'').trim().toLocaleLowerCase();
  const terms=q.split(/\s+/).filter(Boolean);
  const cat=$('catFilter')?.value||'',mode=$('searchMode')?.value||'all';
  const crop=$('searchCropFilter')?.value||'',target=$('searchTargetFilter')?.value||'';
  const hasTerms=hay=>terms.every(t=>hay.includes(t));
  const chemicals=allChemicals().filter(x=>{
    if(mode==='product')return false;
    if(cat&&x.category!==cat)return false;
    if(crop&&!String(x.crops||'').toLocaleLowerCase().includes(crop.toLocaleLowerCase()))return false;
    if(target&&!((target==='कीट'&&/कीट|माइट|मकड़ी|इल्ल/i.test(x.target))||(target==='रोग'&&/रोग|ब्लाइट|मिल्ड्यू|झुलसा/i.test(x.target))||(target==='खरपतवार'&&/खरपतवार/i.test(x.target))||(target==='माइट'&&/माइट/i.test(x.target))))return false;
    const fields=mode==='crop'?[x.crops]:mode==='target'?[x.target]:mode==='technical'?[x.technical]:[x.technical,x.category,x.target,x.crops,x.timing,x.caution,x.check];
    return hasTerms(fields.join(' ').toLocaleLowerCase());
  });
  const foundProducts=products.filter(p=>{
    if(mode==='crop'&&crop&&!String(p.crops||'').toLocaleLowerCase().includes(crop.toLocaleLowerCase()))return false;
    if(mode==='target'&&target&&!String(p.utility||'').toLocaleLowerCase().includes(target.toLocaleLowerCase()))return false;
    if(cat&&p.category!==cat)return false;
    if(crop&&!String(p.crops||'').toLocaleLowerCase().includes(crop.toLocaleLowerCase()))return false;
    const fields=mode==='crop'?[p.crops]:mode==='technical'?[p.technical]:mode==='target'?[p.utility,p.technical]:[p.name,p.company,p.technical,p.category,p.utility,p.crops,p.barcode];
    return mode==='all'||mode==='product'||mode==='technical'||mode==='crop'||mode==='target' ? hasTerms(fields.join(' ').toLocaleLowerCase()) : false;
  });
  const out=$('searchResults');
  if(out)out.innerHTML=(foundProducts.map(cardProduct).join(''))+(chemicals.map(cardChem).join(''))||'<div class="empty">कोई परिणाम नहीं मिला। शब्द या Filter बदलकर देखें।</div>';
  const count=$('searchCount');if(count)count.textContent=`${foundProducts.length} Products · ${chemicals.length} Technical References · ${allChemicals().length} Total Technical Names`;
}
function cardChem(x){return `<article class="item" onclick="showChemDetails(${x.id})"><span class="tag">${esc(x.category)}</span><h3>${esc(x.technical)}</h3><p><b>Target:</b> ${esc(x.target)}</p><p class="muted"><b>Crops:</b> ${esc(x.crops)}</p><span class="muted">👉 227 मास्टर डिटेल देखें</span></article>`}
function cardProduct(p){
  const stock=(p.packs||[]).reduce((n,k)=>n+(parseFloat(k.stock)||0),0);
  return `<article class="item product-card" onclick="showProductDetails('${p.id}')">
    <div class="product-card-main"><div class="row" style="justify-content:space-between"><span class="tag">${esc(p.category)}</span><button class="star-btn" onclick="event.stopPropagation();toggleStar('${p.id}')">${p.starred?'★':'☆'}</button></div>
    <div class="product-headline"><div class="product-thumb">${p.image?`<img src="${esc(p.image)}" alt="" style="width:100%;height:100%;object-fit:cover;border-radius:12px" onerror="this.parentElement.textContent='🌱'">`:"🌱"}</div><div><h3>${esc(p.name)}</h3><p class="product-brand" style="margin:4px 0">${p.logo?`<img class="company-logo" src="${esc(p.logo)}" alt="" onerror="this.style.display='none'">`:"🏢 "}<b>${esc(p.company||'Company not set')}</b><br>🧪 ${esc(p.technical)}</p></div></div>
    ${(p.packs||[]).map(k=>`<p><b>${esc(k.size)}</b> · <span class="price">₹${esc(k.sell||'—')}</span> <span class="tag" style="background:${(parseFloat(k.stock)||0)>0?'#dcfce7':'#fee2e2'};color:${(parseFloat(k.stock)||0)>0?'#166534':'#991b1b'}">Stock ${k.stock||0}</span></p>`).join('')}
    <div class="product-price">Stock Total: ${stock}</div>
    ${p.crops?`<div>${p.crops.split(',').map(c=>`<span class="tag">🌾 ${esc(c.trim())}</span>`).join('')}</div>`:''}${p.utility?`<div class="utility-text"><b>उपयोग / फसल:</b> ${esc(p.utility)}</div>`:''}${p.note?`<div class="quick-note">📝 ${esc(p.note)}</div>`:''}</div>
    <div class="product-card-footer"><button onclick="event.stopPropagation();quickProductNote('${p.id}')">▤ Write / Edit Note</button><button class="secondary" onclick="event.stopPropagation();showProductDetails('${p.id}')">↗ View Details</button></div>
  </article>`;
}

function showChemDetails(id){
  let x=allChemicals().find(c=>c.id===id);
  if(!x)return;
  let matches=products.filter(p=>p.technical.toLowerCase()===x.technical.toLowerCase());
  $('detailContent').innerHTML=`
    <span class="tag">${esc(x.category)}</span>
    <h2>${esc(x.technical)}</h2>
    <p><b>बीमारी / कीट (Target):</b> ${esc(x.target)}</p>
    <p><b>फसल उदाहरण (Crops):</b> ${esc(x.crops)}</p>
    <p><b>सामान्य समय (Timing):</b> ${esc(x.timing)}</p>
    <p><b>सावधानी (Caution):</b> ${esc(x.caution)}</p>
    <p><b>अनिवार्य जाँच (Check):</b> ${esc(x.check)}</p>
    <h3 style="margin-top:15px">🏪 आपके स्टोर पर उपलब्ध इस टेक्निकल के ब्रांड:</h3>
    ${matches.length?matches.map(p=>`<div style="background:var(--soft);padding:8px;border-radius:8px;margin-bottom:6px"><b>${esc(p.name)}</b> (${esc(p.company)})<br>${(p.packs||[]).map(k=>`📦 ${esc(k.size)} · MRP ₹${esc(k.mrp)} · <span class="price">Sell ₹${esc(k.sell)}</span> · Stock: ${esc(k.stock)}`).join('<br>')}</div>`).join(''):'<p class="muted">इस टेक्निकल का कोई ब्रांड अभी आपके स्टोर में नहीं जोड़ा गया है। आप "+ Add Product" से जोड़ सकते हैं।</p>'}
    <button class="secondary" style="margin-top:16px;width:100%" onclick="$('detailModal').classList.remove('open')">बंद करें</button>
  `;
  $('detailModal').classList.add('open');
}

function getChemical(technical){
  let key=String(technical||'').trim().toLowerCase();
  return DB.chemicals.find(x=>x.technical.trim().toLowerCase()===key) ||
    DB.chemicals.find(x=>key && (key.includes(x.technical.toLowerCase())||x.technical.toLowerCase().includes(key)));
}
function chemicalInfoFor(technical){
  let x=getChemical(technical);
  if(!x)return `<div class="notice"><b>🧪 Technical जानकारी:</b> इस नाम का सटीक रिकॉर्ड Chemical Master में नहीं मिला। कृपया उत्पाद के लेबल से Technical Name की पुष्टि करें।</div>`;
  return `<div class="panel" style="background:var(--soft);margin:12px 0">
    <h3>🧪 Chemical के सामान्य कार्य व संदर्भ</h3>
    <p><b>श्रेणी:</b> ${esc(x.category)}</p><p><b>सामान्य लक्ष्य / कार्य:</b> ${esc(x.target)}</p>
    <p><b>सूची में दी गई फसलें:</b> ${esc(x.crops)}</p><p><b>सूची में समय:</b> ${esc(x.timing)}</p>
    <p><b>सावधानी:</b> ${esc(x.caution)}</p><p><b>पुष्टि:</b> ${esc(x.check)}</p>
    <small class="muted">यह Master सूची का सामान्य संदर्भ है, उत्पाद-विशिष्ट उपयोग निर्देश नहीं। वास्तविक फसल, लक्ष्य, मात्रा, समय, प्रतीक्षा अवधि और सुरक्षा के लिए उसी उत्पाद का वैध लेबल/लीफलेट देखें।</small>
  </div>`;
}
function quickProductNote(id){
  let p=products.find(x=>x.id===id);if(!p)return;
  showProductDetails(id);
  setTimeout(()=>{let el=$('detailProductNote');if(el)el.focus()},0);
}
function saveProductNote(id){
  let p=products.find(x=>x.id===id);if(!p)return;
  p.note=$('detailProductNote').value.trim();
  saveAll();renderProducts();renderSearch();
  alert('Product Note सुरक्षित हो गई।');
}
function editProductFromDetail(id){
  const product=products.find(x=>String(x.id)===String(id));
  if(!product){alert('यह Product नहीं मिला।');return}
  $('detailModal').classList.remove('open');
  openProduct(product);
}
function showProductDetails(id){
  let p=products.find(prod=>String(prod.id)===String(id));
  if(!p)return;
  recordRecentProduct(p.id);renderRecent();
  $('detailContent').innerHTML=`
    <span class="tag">${esc(p.category)}</span>
    <h2>${esc(p.name)}</h2>
    <p class="muted"><b>कंपनी:</b> ${esc(p.company)}</p>
    <p class="muted"><b>Technical Name:</b> ${esc(p.technical)}</p>
    ${chemicalInfoFor(p.technical)}
    ${p.utility?`<div class="utility-text"><b>Product Usage / Utility:</b><br>${esc(p.utility)}</div>`:''}
    <div class="note-editor"><h3>📝 Product की अपनी नोट</h3><textarea id="detailProductNote" placeholder="इस ब्रांड के बारे में अपनी जानकारी, ग्राहक की मांग, अनुभव, ध्यान रखने वाली बात आदि लिखें...">${esc(p.note||'')}</textarea><button style="margin-top:8px" onclick="saveProductNote('${p.id}')">नोट सुरक्षित करें</button></div>
    <h3 style="margin-top:15px">पैकिंग, भाव और मार्जिन (Packings & Profit):</h3>
    ${(p.packs||[]).map(k=>{
      let buy=parseFloat(k.buy)||0, sell=parseFloat(k.sell)||0;
      let profit=sell-buy;
      let margin=buy>0?((profit/buy)*100).toFixed(1):0;
      return `<p>📦 <b>${esc(k.size)}</b> · MRP ₹${esc(k.mrp||'—')} · <span class="price">बिक्री ₹${esc(sell)}</span> (खरीद ₹${buy})<br><small style="color:var(--green2)">मुनाफा: ₹${profit.toFixed(2)} (${margin}%)</small> · स्टॉक: ${esc(k.stock||'0')}</p>`;
    }).join('')}
    <div class="row" style="margin-top:16px">
      <button onclick="editProductFromDetail('${p.id}')">✏️ Edit Product</button>
      <button class="danger" onclick="$('detailModal').classList.remove('open');deleteProduct('${p.id}')">Delete</button>
      <button class="secondary" onclick="$('detailModal').classList.remove('open')">बंद करें</button>
    </div>
  `;
  $('detailModal').classList.add('open');
}

// Company-wise inventory summary
function openCompanySummary(){
  $('companySummaryQ').value='';
  $('companySummarySort').value='count';
  renderCompanySummary();
  $('companySummaryModal').classList.add('open');
}
function renderCompanySummary(){
  const query=($('companySummaryQ').value||'').trim().toLowerCase();
  const groups=new Map();
  products.forEach(p=>{
    const company=(p.company||'').trim()||'कंपनी दर्ज नहीं';
    if(!groups.has(company))groups.set(company,{company,products:[],packs:0,stock:0});
    const g=groups.get(company);
    g.products.push(p);
    (p.packs||[]).forEach(k=>{g.packs++;g.stock+=parseFloat(k.stock)||0;});
  });
  let list=[...groups.values()].filter(g=>
    (g.company+' '+g.products.map(p=>p.name+' '+p.technical).join(' ')).toLowerCase().includes(query)
  );
  const sort=$('companySummarySort').value;
  if(sort==='az')list.sort((a,b)=>a.company.localeCompare(b.company));
  else if(sort==='stock')list.sort((a,b)=>b.stock-a.stock||a.company.localeCompare(b.company));
  else list.sort((a,b)=>b.products.length-a.products.length||a.company.localeCompare(b.company));
  const companyCount=groups.size;
  const productCount=products.length;
  const stockCount=products.reduce((n,p)=>n+(p.packs||[]).reduce((m,k)=>m+(parseFloat(k.stock)||0),0),0);
  $('companySummaryStats').innerHTML=`
    <div class="stat"><b>${companyCount}</b><span>कुल कंपनियाँ</span></div>
    <div class="stat"><b>${productCount}</b><span>कुल Products</span></div>
    <div class="stat"><b>${stockCount}</b><span>कुल Stock Qty</span></div>`;
  $('companySummaryResults').innerHTML=list.length?list.map(g=>`
    <div class="panel" style="margin-bottom:9px">
      <div class="row" style="align-items:center">
        <div><h3 style="margin:0 0 4px">🏢 ${esc(g.company)}</h3>
          <span class="muted">${g.products.length} Products · ${g.packs} Packings · Stock ${g.stock}</span></div>
        <span class="tag">${g.products.length} Products</span>
      </div>
      <div style="margin-top:8px;display:grid;gap:5px">
        ${g.products.map(p=>`<div style="padding:7px 9px;background:var(--soft);border-radius:7px">
          <b>${esc(p.name)}</b><div class="muted">🧪 ${esc(p.technical)} · ${esc(p.category)} · ${(p.packs||[]).length} Packings · Stock ${(p.packs||[]).reduce((n,k)=>n+(parseFloat(k.stock)||0),0)}</div>
        </div>`).join('')}
      </div>
    </div>`).join(''):'<div class="empty">अभी कोई कंपनी/Product नहीं मिला। पहले Product जोड़ें।</div>';
}

// 2. PRODUCTS & INVENTORY
function productStock(p){return (p.packs||[]).reduce((n,k)=>n+(parseFloat(k.stock)||0),0)}
function productPrice(p){const vals=(p.packs||[]).map(k=>parseFloat(k.sell)).filter(Number.isFinite);return vals.length?Math.min(...vals):Infinity}
function sortProducts(list,sort){
  const out=[...list];
  if(sort==='name')out.sort((a,b)=>(a.name||'').localeCompare(b.name||''));
  else if(sort==='za')out.sort((a,b)=>(b.name||'').localeCompare(a.name||''));
  else if(sort==='stock')out.sort((a,b)=>productStock(b)-productStock(a));
  else if(sort==='price')out.sort((a,b)=>productPrice(a)-productPrice(b));
  else out.sort((a,b)=>String(b.id).localeCompare(String(a.id),undefined,{numeric:true}));
  return out;
}
function renderProducts(){
  let q=$('prodQ').value.toLowerCase(), cat=$('prodCatFilter').value, stock=$('prodStockFilter').value;
  let list=products.filter(p=>{
    let total=productStock(p);
    return (p.name+' '+p.company+' '+p.technical+' '+(p.utility||'')).toLowerCase().includes(q)&&(!cat||p.category===cat)&&(!stock||(stock==='available'?total>0:stock==='out'?total<=0:!!p.starred));
  });
  list=sortProducts(list,$('prodSort')?.value||'new');
  $('productResults').innerHTML=list.map(cardProduct).join('')||'<div class="empty">अभी कोई Product नहीं जोड़ा गया। ऊपर "+ Add Product" से जोड़ें।</div>';
}
function renderStarred(){
  const q=($('starQ')?.value||'').trim().toLowerCase(),cat=$('starCat')?.value||'',sort=$('starSort')?.value||'name';
  let list=products.filter(p=>p.starred&&(!cat||p.category===cat)&&[p.name,p.company,p.technical,p.category,p.utility].join(' ').toLowerCase().includes(q));
  list=sortProducts(list,sort);
  $('starResults').innerHTML=list.map(cardProduct).join('')||'<div class="empty">अभी कोई Starred Product नहीं है। Product Card पर ☆ दबाकर Bookmark करें।</div>';
}

function openProduct(p=null){
  $('productModal').classList.add('open');
  $('modalTitle').textContent=p&&p.id?'Edit Product':'Add Product';
  $('editId').value=p?.id||'';
  $('pname').value=p?.name||'';
  $('company').value=p?.company||'';
  let tech=p?.technical||'';
  $('technical').value=tech;
  $('techPickerSearch').value=tech;
  $('techPickerCategory').value='';
  $('techPickerSort').value='az';
  filterTechnicalOptions();
  $('technicalSelect').value=tech;
  $('pcat').value=p?.category||'Insecticide';
  $('pbarcode').value=p?.barcode||'';$('pimage').value=p?.image||'';$('plogo').value=p?.logo||'';$('pcrops').value=p?.crops||'';
  $('putility').value=p?.utility||'';
  $('packs').innerHTML='';
  (p?.packs||[{}]).forEach(addPackRow);
}
function closeProduct(){$('productModal').classList.remove('open')}

function addPackRow(v={}){
  let d=document.createElement('div');d.className='panel';
  d.innerHTML=`
    <div class="row">
      <div><label>Packing Size (जैसे 100 ml / 250 gm / 1 L)</label><input class="psize" value="${esc(v.size||'')}"></div>
      <div><label>MRP ₹</label><input class="pmrp" type="number" min="0" step=".01" value="${esc(v.mrp||'')}"></div>
    </div>
    <div class="row">
      <div><label>Purchase Price ₹</label><input class="pbuy" type="number" min="0" step=".01" value="${esc(v.buy||'')}" oninput="calcMargin(this)"></div>
      <div><label>Selling Price ₹</label><input class="psell" type="number" min="0" step=".01" value="${esc(v.sell||'')}" oninput="calcMargin(this)"></div>
      <div><label>Stock Qty</label><input class="pstock" type="number" min="0" value="${esc(v.stock||'0')}"></div>
    </div>
    <p class="margin-info" style="font-size:12px;color:var(--green);margin:4px 0">मुनाफा: —</p>
    <button class="danger" onclick="this.parentElement.remove()">Remove Packing</button>
  `;
  $('packs').append(d);
  if(v.buy||v.sell) calcMargin(d.querySelector('.psell'));
}

function calcMargin(el){
  let pPanel=el.closest('.panel');
  let buy=parseFloat(pPanel.querySelector('.pbuy').value)||0;
  let sell=parseFloat(pPanel.querySelector('.psell').value)||0;
  let info=pPanel.querySelector('.margin-info');
  if(buy>0 && sell>0){
    let prof=sell-buy;
    let pct=((prof/buy)*100).toFixed(1);
    info.textContent=`⚡ अनुमानित मुनाफा: ₹${prof.toFixed(2)} (${pct}%)`;
  }else{
    info.textContent='मुनाफा: —';
  }
}

function saveProduct(){
  let name=$('pname').value.trim();
  if(!name){alert('Product Name भरें');return}
  let technical=$('technical').value.trim();
  if(!technical){alert('Technical Name चुनें या भरें');return}
  let packs=[...$('packs').children].map(d=>({
    size:d.querySelector('.psize').value.trim(),
    mrp:d.querySelector('.pmrp').value,
    buy:d.querySelector('.pbuy').value,
    sell:d.querySelector('.psell').value,
    stock:d.querySelector('.pstock').value
  })).filter(x=>x.size);
  if(!packs.length){alert('कम से कम एक Packing जोड़ें');return}
  if(packs.some(x=>[x.mrp,x.buy,x.sell,x.stock].some(v=>v!==''&&(!Number.isFinite(Number(v))||Number(v)<0)))){
    alert('Packing में MRP, खरीद, बिक्री और Stock की मात्रा शून्य या उससे अधिक सही संख्या में भरें।');return;
  }
  if(packs.some(x=>!x.size)){alert('हर Packing का Size भरें।');return}
  let id=$('editId').value||('p'+Date.now());
  let oldProduct=products.find(x=>x.id===id);
  let obj={id,name,company:$('company').value.trim(),technical,category:$('pcat').value,packs,utility:$('putility').value.trim(),note:oldProduct?.note||'',starred:!!oldProduct?.starred,barcode:$('pbarcode').value.trim(),image:$('pimage').value.trim(),logo:$('plogo').value.trim(),crops:$('pcrops').value.trim()};
  let i=products.findIndex(x=>x.id===id);
  if(i>=0)products[i]=obj;else products.push(obj);
  saveAll();renderProducts();renderSearch();renderHome();renderStarred();renderCompanies();renderPacking();renderStock();closeProduct();
}


function toggleStar(id){
  const p=products.find(x=>String(x.id)===String(id));if(!p)return;
  p.starred=!p.starred;saveAll();renderProducts();renderSearch();renderHome();renderStarred();
  const msg=p.starred?'Product Starred में जोड़ दिया गया।':'Product Starred से हटा दिया गया।';
  // छोटा visual feedback बिना blocking popup के
  const live=$('starFeedback');if(live)live.textContent=msg;
}
function addCustomChemical(){
 const technical=$('newChemName').value.trim();if(!technical){alert('Technical Name भरें');return}
 if(allChemicals().some(x=>x.technical.toLowerCase()===technical.toLowerCase())){alert('यह Technical पहले से मौजूद है।');return}
 const item={id:'custom-'+Date.now(),technical,category:$('newChemCat').value,target:$('newChemTarget').value.trim()||'विवरण उपलब्ध नहीं',crops:$('newChemCrops').value.trim()||'लेबल देखें',timing:$('newChemTiming').value.trim()||'लेबल के अनुसार',caution:$('newChemCaution').value.trim()||'उत्पाद लेबल के अनुसार सुरक्षा रखें',check:'वर्तमान CIBRC / उत्पाद लेबल सत्यापित करें।',custom:true};
 customChemicals.push(item);
 const o=document.createElement('option');o.value=technical;o.textContent=technical+' ('+item.category+')';$('technicalSelect').appendChild(o.cloneNode(true));$('compareTech').appendChild(o);
 saveAll();['newChemName','newChemTarget','newChemCrops','newChemTiming','newChemCaution'].forEach(id=>$(id).value='');renderChem();alert('नया Technical Chemical सेव हो गया।');
}

