// 4. LEDGER & GST
function renderLedger(){
  let q=$('custQ').value.toLowerCase(), balanceFilter=$('ledgerBalanceFilter').value;
  let filtered=customers.filter(c=>{
    let balance=(c.txns||[]).reduce((n,t)=>n+(t.type==='Debit'?1:-1)*(parseFloat(t.amount)||0),0);
    return (c.name+' '+c.phone).toLowerCase().includes(q)&&(!balanceFilter||(balanceFilter==='due'?balance>0:balance<=0));
  });
  if(!filtered.length){$('ledgerResults').innerHTML='<div class="empty">कोई ग्राहक या लेनदेन रिकॉर्ड नहीं मिला।</div>';return;}
  $('ledgerResults').innerHTML=filtered.map(c=>`
    <article class="item" style="cursor:default">
      <div><h3>${esc(c.name)}</h3>
      <p class="muted">📞 ${esc(c.phone)}</p>
      <table>
        <tr><th>दिनांक</th><th>विवरण</th><th>प्रकार</th><th>रुपये</th></tr>
        ${(c.txns||[]).map(t=>`<tr><td>${t.date}</td><td>${esc(t.desc)}</td><td><span class="tag" style="background:${t.type==='Debit'?'#fee2e2':'#dcfce7'};color:${t.type==='Debit'?'#991b1b':'#166534'}">${t.type}</span></td><td>₹${t.amount}</td></tr>`).join('')}
      </table></div>
      <div class="row" style="margin-top:10px">
        <button onclick="openCustomerModal()">+ Add Txn</button>
        <button class="danger" onclick="deleteCustomer('${c.id}')">Delete</button>
      </div>
    </article>
  `).join('');
}

function openCustomerModal(){$('customerModal').classList.add('open');}
function saveCustomerTxn(){
  let name=$('cName').value.trim();
  if(!name){alert('ग्राहक का नाम भरें');return;}
  let phone=$('cPhone').value.trim()||'—';
  let type=$('cType').value;
  let amount=parseFloat($('cAmount').value)||0;
  let desc=$('cDesc').value.trim()||'सामान्य लेन-देन';
  let date=new Date().toLocaleDateString('hi-IN');
  
  let cust=customers.find(c=>c.name.toLowerCase()===name.toLowerCase());
  if(!cust){
    cust={id:'c'+Date.now(), name, phone, txns:[]};
    customers.push(cust);
  }
  cust.txns.push({date, type, amount, desc});
  saveAll();renderLedger();$('customerModal').classList.remove('open');
}
function deleteCustomer(id){
  if(confirm('इस ग्राहक का खाता हटाएँ?')){
    customers=customers.filter(c=>c.id!==id);
    saveAll();renderLedger();
  }
}

