// 7. BACKUP & EXPORT
function downloadBlob(filename, blob){
  const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1200);
}
function getBackupPayload(){
  return {app:'SONBOIR AGRI PRO',schemaVersion:2,exportedAt:new Date().toISOString(),data:{products,customers,notes,sales,purchases,suppliers,customChemicals,recentProducts:getRecentProductIds()}};
}
function backupData(){
  const payload=getBackupPayload();const stamp=new Date().toISOString().slice(0,10);
  downloadBlob('SONBOIR_AGRI_PRO_FULL_BACKUP_'+stamp+'.json',new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));
  const status=$('backupLastStatus');if(status)status.textContent='Last backup: '+new Date().toLocaleString();
}
function restoreData(e){
  const f=e.target.files&&e.target.files[0];if(!f)return;
  const input=e.target;
  const r=new FileReader();
  r.onload=()=>{
    try{
      const parsed=JSON.parse(r.result);const d=parsed.data&&typeof parsed.data==='object'?parsed.data:parsed;
      const keys=['products','customers','notes','sales','purchases','suppliers','customChemicals'];
      const present=keys.filter(k=>Array.isArray(d[k]));
      if(!present.length)throw new Error('इस JSON में SONBOIR का पहचानने योग्य डेटा नहीं मिला।');
      const invalid=present.find(k=>!Array.isArray(d[k]));if(invalid)throw new Error('Invalid '+invalid+' data');
      const counts=present.map(k=>k+': '+d[k].length).join(' · ');
      if(!confirm('Backup file: '+f.name+'\n\n'+counts+'\n\nRestore करने से मौजूदा रिकॉर्ड replace होंगे। पहले वर्तमान डेटा का Safety Backup डाउनलोड होगा। जारी रखें?'))return;
      backupData();
      const old={products,customers,notes,sales,purchases,suppliers,customChemicals};
      present.forEach(k=>{if(k==='products')products=d[k];else if(k==='customers')customers=d[k];else if(k==='notes')notes=d[k];else if(k==='sales')sales=d[k];else if(k==='purchases')purchases=d[k];else if(k==='suppliers')suppliers=d[k];else if(k==='customChemicals')customChemicals=d[k]});
      if(!saveAll()){
        products=old.products;customers=old.customers;notes=old.notes;sales=old.sales;purchases=old.purchases;suppliers=old.suppliers;customChemicals=old.customChemicals;saveAll();
        throw new Error('डेटा सेव नहीं हो पाया। पुराना डेटा वापस रखा गया है।');
      }
      if(Array.isArray(d.recentProducts))localStorage.setItem('sonboir_recent',JSON.stringify(d.recentProducts.slice(0,10)));
      renderAll();refreshTechnicalMasterUI();renderRecent();renderSettingsDataSummary();
      alert('Restore सफल रहा!\n'+counts);
    }catch(err){alert('Import असफल: '+err.message)}finally{input.value=''}
  };
  r.onerror=()=>{alert('फाइल पढ़ी नहीं जा सकी।');input.value=''};
  r.readAsText(f);
}
function csvCell(v){return '"'+String(v??'').replace(/"/g,'""')+'"'}
function exportDatasetCSV(type){
  const config={
    sales:{name:'sales',rows:[['Bill ID','Date','Customer','Product','Company','Packing','Quantity','Price','Discount','Total','Payment'],...sales.map(x=>[x.id,x.date,x.customer,x.product,x.company,x.packing,x.qty,x.price,x.discount,x.total,x.payment])]},
    purchases:{name:'purchases',rows:[['Purchase ID','Date','Supplier','Product','Company','Packing','Quantity','Rate','Total'],...purchases.map(x=>[x.id,x.date,x.supplier,x.product,x.company,x.packing,x.qty,x.price,x.total])]},
    customers:{name:'customers',rows:[['Name','Phone','Address','Opening Balance','Notes'],...customers.map(x=>[x.name,x.phone,x.address,x.balance,x.note])]},
    suppliers:{name:'suppliers',rows:[['Name','Phone','Address','Notes'],...suppliers.map(x=>[x.name,x.phone,x.address,x.note])]}
  }[type];
  if(!config)return;
  const csv=config.rows.map(row=>row.map(csvCell).join(',')).join('\r\n');
  downloadBlob('sonboir-'+config.name+'-'+new Date().toISOString().slice(0,10)+'.csv',new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));
}
function importChemicalsCSV(event){
  const file=event.target.files&&event.target.files[0];if(!file)return;
  const reader=new FileReader();reader.onload=()=>{
    try{
      const lines=String(reader.result||'').replace(/^\ufeff/,'').split(/\r?\n/).filter(x=>x.trim());
      if(lines.length<2)throw new Error('CSV में डेटा नहीं है।');
      const parse=line=>{const out=[];let cur='',quoted=false;for(let i=0;i<line.length;i++){const c=line[i];if(c==='"'&&line[i+1]==='"'&&quoted){cur+='"';i++}else if(c==='"')quoted=!quoted;else if(c===','&&!quoted){out.push(cur);cur=''}else cur+=c}out.push(cur);return out};
      const headers=parse(lines[0]).map(x=>x.trim().toLowerCase());
      const idx=names=>headers.findIndex(h=>names.includes(h));
      const ti=idx(['technical','technical name','technical_name']);if(ti<0)throw new Error('Technical या Technical Name column जरूरी है।');
      const ci=idx(['category']),gi=idx(['target']),cr=idx(['crops']),tm=idx(['timing']),ca=idx(['caution','safety']);
      let added=0,updated=0;const norm=x=>String(x||'').trim().toLowerCase().replace(/\s+/g,' ');
      lines.slice(1).forEach(line=>{const row=parse(line),technical=(row[ti]||'').trim();if(!technical)return;const item={id:'custom_'+Date.now()+'_'+Math.random().toString(36).slice(2,7),technical,category:ci>=0?row[ci]||'Other':'Other',target:gi>=0?row[gi]||'':'',crops:cr>=0?row[cr]||'':'',timing:tm>=0?row[tm]||'':'',caution:ca>=0?row[ca]||'':''};const existing=customChemicals.find(x=>norm(x.technical)===norm(technical));if(existing){Object.assign(existing,item,{id:existing.id});updated++}else if(!DB.chemicals.some(x=>norm(x.technical)===norm(technical))){customChemicals.push(item);added++}});
      saveAll();refreshTechnicalMasterUI();renderChem();renderSettingsDataSummary();alert('Technical CSV Import पूरा हुआ।\nनए: '+added+' · अपडेट: '+updated+' · कुल Master: '+allChemicals().length);
    }catch(err){alert('Technical CSV Import असफल: '+err.message)}finally{event.target.value=''}
  };reader.readAsText(file);
}
function renderSettingsDataSummary(){
  const put=(id,n)=>{const el=$(id);if(el)el.textContent=Number(n||0).toLocaleString('en-IN')};
  put('dataProductCount',products.length);put('dataCompanyCount',new Set(products.map(p=>(p.company||'').trim()).filter(Boolean)).size);put('dataPackCount',products.reduce((n,p)=>n+(p.packs||[]).length,0));put('dataCustomerCount',customers.length);put('dataSalesCount',sales.length);put('dataTechCount',allChemicals().length);
}
function exportStoreExcel(){
  let rows=[['Product Name','Company','Technical Name','Category','Packing Size','MRP','Purchase Price','Selling Price','Stock']];
  products.forEach(p=>{
    (p.packs||[]).forEach(k=>{
      rows.push([p.name, p.company, p.technical, p.category, k.size, k.mrp, k.buy, k.sell, k.stock]);
    });
  });
  let csv=rows.map(r=>r.map(csvCell).join(',')).join('\r\n');
  downloadBlob('sonboir-products-inventory.csv',new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));
}
function exportChemCSV(){
  let rows=[['Technical','Category','Target','Crops','Timing','Caution'],...allChemicals().map(x=>[x.technical,x.category,x.target,x.crops,x.timing,x.caution])];
  let csv=rows.map(r=>r.map(csvCell).join(',')).join('\r\n');
  downloadBlob('sonboir-chemical-master.csv',new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));
}



