function showSeasonal(crop){const list=crop==='सभी'?products:products.filter(p=>(p.crops||'').toLowerCase().includes(crop.toLowerCase())||(p.utility||'').toLowerCase().includes(crop.toLowerCase()));$('seasonalResults').innerHTML=list.length?list.map(cardProduct).join(''):`<div class="empty">${crop} के लिए कोई Product दर्ज नहीं है। Product में Applicable Crops भरें।</div>`}
function updateQuickCalc(){const total=Math.max(0,(+$('quickPrice').value||0)*(+$('quickQty').value||0)-(+$('quickDiscount').value||0));$('quickTotal').textContent='कुल: ₹'+total.toFixed(2)}
function printInvoice(id){const x=sales.find(s=>s.id===id);if(!x)return;const storeName='SONBOIR AGRI PRO';$('invoiceContent').innerHTML=`<div id="invoicePrint" class="invoice-paper"><div style="text-align:center;border-bottom:2px solid #14532d;padding-bottom:12px"><h2 style="margin:0">${storeName}</h2><p>कृषि उत्पाद एवं बीज भंडार</p><b>SALES INVOICE</b></div><p><b>Bill No:</b> ${esc(x.id)} &nbsp; <b>Date:</b> ${esc(x.date)}</p><p><b>Customer:</b> ${esc(x.customer)} &nbsp; <b>Payment:</b> ${esc(x.payment)}</p><table><thead><tr><th>Product</th><th>Company</th><th>Packing</th><th>Qty</th><th>Rate</th><th>Amount</th></tr></thead><tbody><tr><td>${esc(x.product)}</td><td>${esc(x.company||'')}</td><td>${esc(x.packing)}</td><td>${esc(x.qty)}</td><td>₹${(+x.price).toFixed(2)}</td><td>₹${(+x.qty*+x.price).toFixed(2)}</td></tr></tbody></table><h3 style="text-align:right">Discount: ₹${(+x.discount||0).toFixed(2)}<br>Grand Total: ₹${(+x.total).toFixed(2)}</h3><p style="margin-top:45px">Customer Signature __________________ &nbsp;&nbsp; Authorized Signatory __________________</p></div>`;$('invoiceModal').classList.add('open')}

