  if(id==='settings')renderSettingsDataSummary();
  if(id==='home')renderHome();
  if(id==='companies')renderCompanies();
  if(id==='packing')renderPacking();
  if(id==='stock')renderStock();
  if(id==='billing'){refreshPackSelectors();renderSales()}
  if(id==='purchase'){refreshPackSelectors();renderPurchases()}
  if(id==='suppliers')renderSuppliers();
