function renderReports(){
  const stock=packOptions().reduce((n,x)=>n+x.stock,0),salesTotal=sales.reduce((n,x)=>n+(+x.total||0),0),purchaseTotal=purchases.reduce((n,x)=>n+(+x.qty||0)*(+x.price||0),0);
  $('reportStats').innerHTML=`<div class="stat"><b>₹${salesTotal.toFixed(0)}</b><span>Total Sales</span></div><div class="stat"><b>₹${purchaseTotal.toFixed(0)}</b><span>Purchase Value</span></div><div class="stat"><b>${stock}</b><span>Current Stock</span></div><div class="stat"><b>${sales.length}</b><span>Sales Bills</span></div><div class="stat"><b>${purchases.length}</b><span>Purchase Entries</span></div>`;
  const map=new Map();products.forEach(p=>{const c=p.company||'कंपनी दर्ज नहीं';map.set(c,(map.get(c)||0)+(p.packs||[]).reduce((n,k)=>n+(+k.stock||0),0))});
  $('reportCompanies').innerHTML=[...map].map(([c,n])=>`<div class="module-card"><h3>${esc(c)}</h3><b>${n}</b><span class="muted">Stock Qty</span></div>`).join('')||'<div class="empty">No data</div>';
  $('reportTransactions').innerHTML=`<table><thead><tr><th>Type</th><th>Date</th><th>Details</th><th>Amount</th></tr></thead><tbody>${sales.slice(0,15).map(x=>`<tr><td>Sale</td><td>${esc(x.date)}</td><td>${esc(x.product)} · ${esc(x.customer)}</td><td>₹${(+x.total).toFixed(2)}</td></tr>`).join('')}${purchases.slice(0,15).map(x=>`<tr><td>Purchase</td><td>${esc(x.date)}</td><td>${esc(x.product)} · ${esc(x.supplier)}</td><td>₹${(+x.qty*+x.price).toFixed(2)}</td></tr>`).join('')}</tbody></table>`;
}
