/* Compact bilingual interface dictionary; product data is never translated or modified. */
const SONBOIR_I18N={
  en:{
    'Dashboard':'Dashboard','Product Master':'Product Master','Starred / Bookmarks':'Starred / Bookmarks',
    'Company & Brand Master':'Company & Brand Master','Packing Master':'Packing Master','Stock Management':'Stock Management',
    'Sales / Billing':'Sales / Billing','Purchase':'Purchase','Customers':'Customers','Suppliers':'Suppliers','Reports':'Reports',
    'Smart Search':'Smart Search','Multi-Brand View':'Multi-Brand View','Notes System':'Notes System',
    'Chemical Master (227)':'Chemical Master','Backup / Data':'Backup / Data','Settings':'Settings','Help':'Help',
    'Main Menu':'Main Menu','Tools & Settings':'Tools & Settings','Appearance':'Appearance','Data Backup':'Data Backup',
    'Export':'Export','कंपनी सूची, उनके ब्रांड और स्टॉक का सारांश':'Company list, brands and stock summary',
    'सभी Products की पैकिंग, MRP, खरीद और बिक्री भाव':'Packing, MRP, purchase and selling prices',
    'मौजूदा स्टॉक देखें और मात्रा अपडेट करें':'View current stock and update quantity',
    'आपकी दुकान का आज का Store Overview':'Your store overview',
    'फसल के अनुसार Products':'Products by crop','हाल ही में देखे गए':'Recently viewed',
    'Product, Company & Packing Master':'Product, Company & Packing Master',
    'सॉफ्टवेयर की सामान्य सेटिंग और डेटा सुरक्षा':'General software settings and data security',
    'हिन्दी (Hindi)':'Hindi','कंपनी दर्ज नहीं':'Company not entered'
  },
  hi:{}
};
function setLanguage(lang){
  const value=lang==='en'?'en':'hi';
  localStorage.setItem('sonboir_language',value);
  const s=$('languageSetting');if(s)s.value=value;
  applyLanguage(value);
}
function applyLanguage(lang){
  const dict=SONBOIR_I18N[lang]||{};
  document.querySelectorAll('button,.drawer-label,.drawer-name,.drawer-role,.page-head p,.page-head h2,.module-card h3,.stat span,label,footer').forEach(el=>{
    if(!el.dataset.originalText)el.dataset.originalText=el.textContent.trim();
    const original=el.dataset.originalText;
    if(lang==='en'&&dict[original])el.textContent=dict[original];
    else if(lang==='hi')el.textContent=original;
  });
  document.querySelectorAll('input[placeholder],textarea[placeholder]').forEach(el=>{
    if(!el.dataset.originalPlaceholder)el.dataset.originalPlaceholder=el.placeholder;
    const original=el.dataset.originalPlaceholder;
    if(lang==='en'&&dict[original])el.placeholder=dict[original];
    else if(lang==='hi')el.placeholder=original;
  });
  document.documentElement.lang=lang;
}
const _savedLang=localStorage.getItem('sonboir_language')||'hi';
applyLanguage(_savedLang);
if($('languageSetting'))$('languageSetting').value=_savedLang;
if($('themeSetting'))$('themeSetting').value=document.body.dataset.theme;
