/* Universal Product Master filters and live result count */
function refreshUniversalFilters(){
  const cf=$('prodCompanyFilter'), tf=$('prodTechFilter');
  if(!cf||!tf)return;
  const oldC=cf.value,oldT=tf.value;
  const companies=[...new Set(products.map(p=>(p.company||'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b));
  const techs=[...new Set(products.map(p=>(p.technical||'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b));
  cf.innerHTML='<option value="">सभी कंपनियाँ ('+companies.length+')</option>'+companies.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');
  tf.innerHTML='<option value="">सभी Technical Names ('+techs.length+')</option>'+techs.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');
  cf.value=companies.includes(oldC)?oldC:'';
  tf.value=techs.includes(oldT)?oldT:'';
}
const _renderProductsUniversal=renderProducts;
renderProducts=function(){
  if(!$('prodQ'))return;refreshUniversalFilters();
  const q=($('prodQ').value||'').trim().toLocaleLowerCase(),terms=q.split(/\s+/).filter(Boolean);
  const cat=$('prodCatFilter').value,stock=$('prodStockFilter').value,company=$('prodCompanyFilter')?.value||'',technical=$('prodTechFilter')?.value||'';
  let list=products.filter(p=>{
    const total=productStock(p),hay=[p.name,p.company,p.technical,p.category,p.utility,p.crops,p.barcode,(p.packs||[]).map(k=>k.size).join(' ')].join(' ').toLocaleLowerCase();
    return terms.every(t=>hay.includes(t))&&(!cat||p.category===cat)&&(!company||(p.company||'').trim()===company)&&(!technical||p.technical===technical)&&(!stock||(stock==='available'?total>0:stock==='out'?total<=0:!!p.starred));
  });
  const sort=$('prodSort')?.value||'new';
  list.sort((a,b)=>{if(sort==='name')return (a.name||'').localeCompare(b.name||'');if(sort==='nameDesc')return (b.name||'').localeCompare(a.name||'');if(sort==='company')return (a.company||'').localeCompare(b.company||'');if(sort==='technical')return (a.technical||'').localeCompare(b.technical||'');if(sort==='stockHigh')return productStock(b)-productStock(a);if(sort==='stockLow')return productStock(a)-productStock(b);return (Number(String(b.id).replace(/\D/g,''))||0)-(Number(String(a.id).replace(/\D/g,''))||0)});
  $('productResults').innerHTML=list.map(cardProduct).join('')||'<div class="empty">कोई Product नहीं मिला। Search या Filter बदलकर देखें।</div>';
  const count=$('productFilterCount');if(count)count.textContent=`${list.length} / ${products.length} Products · ${new Set(list.map(p=>p.company).filter(Boolean)).size} Companies · ${new Set(list.map(p=>p.technical).filter(Boolean)).size} Technical Names · ${list.reduce((n,p)=>n+(p.packs||[]).length,0)} Packings`;
};
function refreshCompanyFilters(){
  const sel=$('companyTechFilter');if(!sel)return;
  const old=sel.value;const techs=[...new Set(products.map(p=>String(p.technical||'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b));
  sel.innerHTML='<option value="">सभी Technical Names ('+techs.length+')</option>'+techs.map(t=>`<option value="${esc(t)}">${esc(t)}</option>`).join('');sel.value=techs.includes(old)?old:'';
}
function renderCompanies(){
  if(!$('companyResults'))return;refreshCompanyFilters();
  const q=($('companyQ')?.value||'').trim().toLocaleLowerCase(),terms=q.split(/\s+/).filter(Boolean);
  const category=$('companyCategoryFilter')?.value||'',technical=$('companyTechFilter')?.value||'';
  const map=new Map();products.forEach(p=>{const name=(p.company||'कंपनी दर्ज नहीं').trim();if(!map.has(name))map.set(name,[]);map.get(name).push(p)});
  let rows=[...map].map(([name,all])=>[name,all.filter(p=>(!category||p.category===category)&&(!technical||p.technical===technical)&&terms.every(t=>[name,p.name,p.company,p.technical,p.category,p.utility,p.crops].join(' ').toLocaleLowerCase().includes(t))) ]).filter(([,ps])=>ps.length);
  const sort=$('companySort')?.value||'az';rows.sort((a,b)=>sort==='za'?b[0].localeCompare(a[0]):sort==='products'?b[1].length-a[1].length:sort==='technical'?new Set(a[1].map(p=>p.technical)).size-new Set(b[1].map(p=>p.technical)).size:a[0].localeCompare(b[0]));
  const shownProducts=rows.reduce((n,x)=>n+x[1].length,0),shownTech=new Set(rows.flatMap(x=>x[1].map(p=>p.technical).filter(Boolean))).size;
  if($('companyFilterCount'))$('companyFilterCount').textContent=`${rows.length} / ${map.size} Companies · ${shownProducts} / ${products.length} Products · ${shownTech} Technical Names`;
  $('companyResults').innerHTML=rows.length?rows.map(([name,ps])=>`<div class="module-card"><h3>🏢 ${esc(name)}</h3><span class="muted">${ps.length} Products · ${ps.reduce((n,p)=>n+(p.packs||[]).length,0)} Packings · ${new Set(ps.map(p=>p.technical).filter(Boolean)).size} Technical Names</span>${ps.map(p=>`<p style="margin:6px 0"><b>${esc(p.name)}</b><br><small class="muted">${esc(p.technical)}</small></p>`).join('')}<button class="secondary" onclick="openCompanyProducts(decodeURIComponent('${encodeURIComponent(name)}'))">View Products</button></div>`).join(''):'<div class="empty">कोई Company / Product नहीं मिला। Search या Filters बदलकर देखें।</div>';
}
cardChem=function(x){return `<article class="item" onclick="${x.custom ? '' : `showChemDetails(${Number(x.id)||0})`}"><span class="tag">${esc(x.category)}</span><h3>${esc(x.technical)}</h3><p><b>Target:</b> ${esc(x.target)}</p><p class="muted"><b>Crops:</b> ${esc(x.crops)}</p>${x.custom?`<button class="danger" onclick="event.stopPropagation();deleteCustomChemical('${String(x.id).replace(/'/g,"\\'")}')">Delete Custom</button>`:'<span class="muted">Master reference entry</span>'}</article>`};
renderChem=function(){
  if(!$('chemResults'))return;
  const q=($('chemQ')?.value||'').trim().toLocaleLowerCase(),terms=q.split(/\s+/).filter(Boolean),cat=$('chemCatFilter')?.value||'';
  let a=allChemicals().filter(x=>(!cat||x.category===cat)&&terms.every(t=>[x.technical,x.category,x.target,x.crops,x.timing,x.caution,x.check].join(' ').toLocaleLowerCase().includes(t)));
  const sort=$('chemSort')?.value||'az';if(sort==='az')a.sort((x,y)=>x.technical.localeCompare(y.technical));else if(sort==='za')a.sort((x,y)=>y.technical.localeCompare(x.technical));else a.sort((x,y)=>Number(x.id)-Number(y.id));
  if($('chemFilterCount'))$('chemFilterCount').textContent=`${a.length} / ${allChemicals().length} Technical Names · ${DB.chemicals.length} Excel Master + ${Math.max(0,allChemicals().length-DB.chemicals.length)} Custom`;
  $('chemResults').innerHTML=a.map(cardChem).join('')||'<div class="empty">कोई Technical Name नहीं मिला।</div>';
};
/* Custom technical count is always derived from master + custom records.
   Built-in master entries are protected; only user-added entries can be removed. */
function deleteCustomChemical(id){
  const item=customChemicals.find(x=>String(x.id)===String(id));
  if(!item)return;
  if(!confirm(`"${item.technical}" को Custom Technical Master से हटाएँ?`))return;
  customChemicals=customChemicals.filter(x=>String(x.id)!==String(id));
  saveAll();refreshTechnicalMasterUI();renderChem();renderProducts();renderSearch();
}
function refreshTechnicalMasterUI(){
  const count=allChemicals().length;
  if($('chemCount'))$('chemCount').textContent=count;
  const title=document.querySelector('#chem .page-head h2, #chem h2');if(title)title.textContent=`Chemical Master (${count} Entries)`;
  document.querySelectorAll('[data-tab="chem"]').forEach(x=>{if(!x.dataset.baseLabel)x.dataset.baseLabel=x.textContent.replace(/\s*\(\d+\)/,'');x.textContent=x.dataset.baseLabel+` (${count})`});
  document.querySelectorAll('[data-go="chem"]').forEach(x=>{if(!x.dataset.baseLabel)x.dataset.baseLabel=x.textContent.replace(/\s*\(\d+\)/,'');x.textContent=x.dataset.baseLabel+` (${count})`});
  if($('techPickerCount'))$('techPickerCount').textContent=`${count} Technical Names`;
  if(typeof filterTechnicalOptions==='function')filterTechnicalOptions();
  if($('compareTech')){const current=$('compareTech').value;$('compareTech').innerHTML='<option value="">-- Technical Name चुनें --</option>'+allChemicals().map(x=>`<option value="${esc(x.technical)}">${esc(x.technical)} (${esc(x.category)})</option>`).join('');$('compareTech').value=current;}
  if($('chemCatFilter')){const current=$('chemCatFilter').value;const cats=[...new Set(allChemicals().map(x=>x.category))].sort();$('chemCatFilter').innerHTML='<option value="">सभी श्रेणियाँ</option>'+cats.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');$('chemCatFilter').value=current;}
}
