/* CSV import: accepts the exported Product CSV headings; safely merges by Product + Company + Technical. */
function importProductsCSV(event){
  const file=event.target.files?.[0];if(!file)return;
  const reader=new FileReader();
  reader.onload=()=>{
    try{
      const raw=String(reader.result||'').replace(/^\uFEFF/,'');
      const lines=raw.split(/\r?\n/).filter(x=>x.trim());
      if(lines.length<2)throw new Error('CSV में data rows नहीं हैं।');
      const parseLine=line=>{const out=[];let cur='',quoted=false;for(let i=0;i<line.length;i++){const c=line[i];if(c==='"'&&line[i+1]==='"'&&quoted){cur+='"';i++}else if(c==='"')quoted=!quoted;else if(c===','&&!quoted){out.push(cur);cur=''}else cur+=c}out.push(cur);return out};
      const head=parseLine(lines[0]).map(x=>x.trim().toLowerCase());
      const idx=(...names)=>head.findIndex(h=>names.includes(h));
      const n=idx('product name','product','name'),co=idx('company','company name'),te=idx('technical name','technical'),ca=idx('category'),pa=idx('packing size','packing','size');
      if(n<0||pa<0)throw new Error('CSV headers Product Name और Packing Size जरूरी हैं।');
      let added=0,updated=0;
      lines.slice(1).forEach(line=>{
        const r=parseLine(line);const name=(r[n]||'').trim(),company=co>=0?(r[co]||'').trim():'',technical=te>=0?(r[te]||'').trim():'';
        if(!name)return;
        let p=products.find(x=>x.name.toLowerCase()===name.toLowerCase()&&(x.company||'').toLowerCase()===company.toLowerCase()&&(x.technical||'').toLowerCase()===technical.toLowerCase());
        if(!p){p={id:'p'+Date.now()+Math.random().toString(16).slice(2,6),name,company,technical,category:ca>=0?(r[ca]||'Other'):'Other',packs:[]};products.push(p);added++}else updated++;
        const val=(key)=>{const j=idx(key);return j>=0?(r[j]||''):''};
        const size=(r[pa]||'').trim();
        if(size){
          const pack={size,mrp:val('mrp'),buy:val('purchase price'),sell:val('selling price'),stock:val('stock')||0};
          const old=(p.packs||[]).find(x=>String(x.size).toLowerCase()===size.toLowerCase());
          if(old)Object.assign(old,pack);else{p.packs=p.packs||[];p.packs.push(pack)}
        }
      });
      saveAll();renderAll();renderProducts();renderCompanies();alert(`CSV Import पूरा हुआ। नए Products: ${added}, अपडेट: ${updated}`);
    }catch(err){alert('CSV Import नहीं हुआ: '+err.message)}
    event.target.value='';
  };
  reader.readAsText(file);
}

